+      session?.token ||
+      session?.accessToken ||
+      session?.authToken ||
+      session?.jwt ||
+      session?.user?.token ||
+      session?.user?.accessToken ||
+      null
+    );
+  } catch (error) {
+    console.error("Unable to read session:", error);
+    return null;
+  }
